-- Extend owner durable DAGs only to reviewed fixed-provider metadata GETs.
-- No sensitive, approval-gated, model-cost, asynchronous or mutation delegation.
BEGIN;
ALTER TABLE public.sandy_orch_delegated_operations ADD COLUMN provider_contract_sha256 text CHECK(provider_contract_sha256 IS NULL OR provider_contract_sha256 ~ '^[a-f0-9]{64}$');
ALTER TABLE public.sandy_orch_delegated_operations DROP CONSTRAINT sandy_orch_delegated_operations_handler_check;
ALTER TABLE public.sandy_orch_delegated_operations ADD CONSTRAINT sandy_orch_delegated_operations_handler_check CHECK(handler IN ('sandy-provider-read-api','sandy-infrastructure-read','sandy-provider-operation-api'));
CREATE OR REPLACE FUNCTION public.sandy_orch_snapshot(p_operation text,p_channel text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT jsonb_build_object('operation',r.operation,'handler',r.handler,'permission_scope',r.permission_scope,
  'is_mutation',r.is_mutation,'input_schema',r.input_schema,'output_schema',r.output_schema,
  'api_exposed',r.api_exposed,'ai_exposed',r.ai_exposed,'verified',r.verified)
 FROM public.sandy_operation_registry r JOIN public.sandy_orch_delegated_operations d ON d.operation=r.operation AND d.handler=r.handler AND d.enabled
 WHERE r.operation=p_operation AND r.api_exposed=true AND r.is_mutation=false
 AND r.permission_scope IN ('infrastructure:read','deployment:read','engineering:read','system:read')
 AND (p_channel='api' OR (p_channel='mcp' AND r.ai_exposed=true))
 AND (r.handler<>'sandy-provider-operation-api' OR (
  d.provider_contract_sha256 IS NOT NULL AND r.error_contract->>'contract_sha256'=d.provider_contract_sha256
  AND r.error_contract->>'api_key_delegable'='true' AND r.error_contract->>'requires_grant'='false'
  AND r.error_contract->>'requires_approval'='false' AND r.error_contract->>'requires_cost_approval'='false'
  AND r.error_contract->>'sensitive_response'='false'))
$$;
-- Exact source-contract eligibility rows follow; mismatching live rows are skipped.
COMMIT;
